def has_exactly_one_dot(file_name):
    return file_name.count('.') == 1

def starts_with_letter(file_name):
    return file_name.split('.')[0].isalpha()

def ends_with_valid_extension(file_name):
    valid_extensions = ['txt', 'exe', 'dll']
    return file_name.split('.')[-1] in valid_extensions

def file_name_check(file_name):
    if not file_name:
        return 'No'

    if not has_less_than_three_digits(file_name):
        return 'No'

    if not has_exactly_one_dot(file_name):
        return 'No'

    if not starts_with_letter(file_name):
        return 'No'

    if not ends_with_valid_extension(file_name):
        return 'No'

    return 'Yes'

